INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-3', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，自安定還，留夏侯淵屯長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-4', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超餘衆梁興等屯藍田，使夏侯淵擊平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-5', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂徙金城，入氐王千萬部，率羌、胡萬餘騎與夏侯淵戰，擊，大破之，遂走西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-6', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，公自南鄭還，留夏侯淵屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-7', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏侯淵與劉備戰於陽平，為備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-004-8', 'p0016', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-008-9', 'p0016', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖遣夏侯淵討破之，雄鳴南奔漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-10', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏略曰：時夏侯淵與惇俱為將軍，軍中號惇為盲夏侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-11', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '文帝少與楙親，及即位，以為安西將軍、持節，承夏侯淵處都督關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-12', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯淵字妙才，惇族弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-13', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏書曰：淵為將，赴急疾，常出敵之不意，故軍中為之語曰：「典軍校尉夏侯淵，三日五百，六日一千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-14', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '是時，夏侯淵沒於陽平，太祖憂之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-014-15', 'p0016', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '又自往拔出夏侯淵軍，數言『南鄭直為天獄，中斜谷道為五百里石穴耳』，言其深險，喜出淵軍之辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-015-16', 'p0016', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '其後與曹洪破吳蘭於下辯，又與夏侯淵討宋建，別攻臨洮、狄道，平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-015-17', 'p0016', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '及夏侯淵還，使閻行留後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-016-18', 'p0016', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖使夏侯淵就助郡擊之，渾率吏民前登，斬興及其支黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-19', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯淵圍昌豨於東海，數月糧盡，議引軍還，遼謂淵曰：「數日已來，每行諸圍，豨輒屬目視遼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-20', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯淵討鄜賊梁興及武都氐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-21', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至陽平，魯降，太祖還，留郃與夏侯淵等守漢中，拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-22', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遂破超等，使晃與夏侯淵平隃麋、汧諸氐，與太祖會安定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-23', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，使晃與夏侯淵平鄜、夏陽餘賊，斬梁興，降三千餘戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-24', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，留晃與夏侯淵拒劉備於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-25', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '又與于禁討昌豨，與夏侯淵討黃巾餘賊徐和等，有功，遷徐州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-26', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '虔引兵與夏侯淵會擊之，前後數十戰，斬首獲生數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-27', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '超復圍州所治兾城甚急，州乃遣溫密出，告急於夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-023-28', 'p0016', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '夏侯淵為劉備所沒，軍喪元帥，將士失色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-026-29', 'p0016', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖還，留征西將軍夏侯淵拒劉備，以淮為淵司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-030-30', 'p0016', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '超破之後，阿貴為夏侯淵所攻滅，千萬西南入蜀，其部落不能去，皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-032-31', 'p0016', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公使夏侯淵、張郃屯漢中，數數犯暴巴界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-035-32', 'p0016', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '今蜀、魏為敵戰之國，勢不俱王，自操、備時，彊弱縣殊，而備猶出兵陽平，禽夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-33', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-34', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安二十四年，於漢中定軍山擊夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-35', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '夏侯淵敗，曹公爭漢中地，運米北山下，數千萬囊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-037-36', 'p0016', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-040-37', 'p0016', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '旣亡漢中，使夏侯淵、張郃深入于巴，幾喪一州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-043-38', 'p0016', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魯已還南鄭，北降曹公，然卒破杜濩、朴胡，殺夏侯淵，據漢中，皆權本謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-054-39', 'p0016', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '左將軍在漢中，為夏侯淵所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-003-0', 'p0017', 'houhanshu', 'a03-003', '《後漢書·卷三》', '孝宣皇帝以為去聖乆遠，學不厭博，故遂立大、小夏侯尚書，後又立京氏易。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-026-1', 'p0017', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '少博學，以大夏侯尚書敎授，大夏侯名勝，宣帝時人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-027-2', 'p0017', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '少好學，習小夏侯尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-027-3', 'p0017', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '又治尚書，學通師法，東觀記曰：「良習大夏侯尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-036-4', 'p0017', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '逵悉傳父業，弱冠能誦左氏傳及五經本文，以大夏侯尚書敎授，雖為古學，兼通五家穀梁之說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-036-5', 'p0017', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '逵數為帝言古文尚書與經傳爾雅詁訓相應，詔令撰歐陽、大小夏侯尚書古文同異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-041-6', 'p0017', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '父京，以大夏侯尚書敎授，夏侯勝也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-079-7', 'p0017', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '中興，北海牟融習大夏侯尚書，東海王良習小夏侯尚書，沛國桓榮習歐陽尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-003-8', 'p0017', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」達旣為文帝所寵，又與桓階、夏侯尚親善，及文帝崩，時桓、尚皆卒，達自以羈旅久在疆場，心不自安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-004-9', 'p0017', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-009-10', 'p0017', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '與夏侯尚等征孫權，擊牛渚屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-009-11', 'p0017', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯尚字伯仁，淵從子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-010-12', 'p0017', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '及彧卒，惲又與植善，而與夏侯尚不穆，文帝深恨惲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-014-13', 'p0017', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大駕幸宛，征南大將軍夏侯尚等攻江陵，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-014-14', 'p0017', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時有詔，詔征南將軍夏侯尚曰：「卿腹心重將，時當任使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-015-15', 'p0017', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：儒字俊林，夏侯尚從弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-015-16', 'p0017', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖善之，拜諫議大夫，與夏侯尚並掌軍計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-017-17', 'p0017', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '詔郃與曹真討安定盧水胡及東羌，召郃與真並朝許宮，遣南與夏侯尚擊江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-017-18', 'p0017', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯尚討劉備於上庸，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-018-19', 'p0017', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與夏侯尚圍江陵，使聘別屯沔口，止石梵，自當一隊，禦賊有功，遷後將軍，封新野侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-019-20', 'p0017', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '乃對中領軍夏侯尚叩頭求哀，尚為涕泣而不能救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-023-21', 'p0017', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時夏侯尚暱於太子，情好至密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-040-22', 'p0017', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '遣征南將軍夏侯尚、右將軍徐晃與達共襲封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-047-23', 'p0017', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-052-24', 'p0017', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：曹真、夏侯尚等圍朱然於江陵，又分據中州，瑾以大兵為之救援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-055-25', 'p0017', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將夏侯尚等圍南郡，分前部三萬人作浮橋，渡百里洲上，諸葛瑾、楊粲並會兵赴救，未知所出，而魏兵日渡不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-056-26', 'p0017', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏遣曹真、夏侯尚、張郃等攻江陵，魏文帝自住宛，為其勢援，連屯圍城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a05-013-27', 'p0017', 'jinshu', 'a05-013', '《晉書·卷十三》', '四月，征南大將軍夏侯尚薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-009-0', 'p0018', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏氏春秋曰：初，夏侯霸將奔蜀，呼玄欲與之俱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-022-1', 'p0018', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後年，雍州刺史王經白泰，云姜維、夏侯霸欲三道向祁山、石營、金城，求進兵為翅，使涼州軍至枹，討蜀護軍向祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-026-2', 'p0018', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '討蜀護軍夏侯霸督諸軍屯為翅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-026-3', 'p0018', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」乃別遣夏侯霸等追維於沓中，淮自率諸軍就攻化等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-028-4', 'p0018', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：夏侯霸奔蜀，蜀朝問「司馬公如何德」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-028-5', 'p0018', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-033-6', 'p0018', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十二年春正月，魏誅大將軍曹爽等，右將軍夏侯霸來降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-036-7', 'p0018', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-043-8', 'p0018', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '嶷至，拜盪寇將軍，慷慨壯烈，士人咸多貴之，然放蕩少禮，人亦以此譏焉，益部耆舊傳曰：時車騎將軍夏侯霸謂嶷曰：「雖與足下踈闊，然託心如舊，宜明此意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-044-9', 'p0018', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '又出隴西、南安、金城界，與魏大將軍郭淮、夏侯霸等戰於洮西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-044-10', 'p0018', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '維乘勝多所降下，拔河間、狄道、臨洮三縣民還，後十八年，復與車騎將軍夏侯霸等俱出狄道，大破魏雍州刺史王經於洮西，經衆死者數萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a05-034-11', 'p0018', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '夏侯霸之降蜀也，姻親多告絕，祜獨安其室，恩禮有加焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-004-0', 'p0019', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚戌，中書令李豐與皇后父光祿大夫張緝等謀廢易大臣，以太常夏侯玄為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-004-1', 'p0019', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之案夏侯玄傳及魏略，許允此年春與李豐事相連。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-2', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時征西將軍夏侯玄，於霸為從子，而玄於曹爽為外弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-3', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '漢晉春秋曰：司馬宣王謂夏侯玄曰：「春秋責大德重，昔武皇帝再入漢中，幾至大敗，君所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-4', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯玄為征西將軍，以勝為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-5', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏氏春秋曰：初，夏侯玄、何晏等名盛於時，司馬景王亦預焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-6', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正始中，夏侯玄盛有名勢，貞嘗在玄坐作五言詩，玄嘉玩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-7', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏弱冠知名，傅子曰：是時何晏以材辯顯於貴戚之間，鄧颺好變通，合徒黨，鬻聲名於閭閻，而夏侯玄以貴臣子少有重名，為之宗主，求交於嘏而不納也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-8', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '愚以為夏侯玄以名重致患，釁由外至；鍾會以利動取敗，禍自己出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-9', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」豐後為中書令，與夏侯玄俱禍，卒如嘏言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-022-10', 'p0019', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹爽輔政，使夏侯玄宣指，欲引臻入守尚書令，及為弟求婚，皆不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-023-11', 'p0019', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '常慕其舅夏侯玄之為人，厚自封植，嶷然不羣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-023-12', 'p0019', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '義子豐，字宣國，見夏侯玄傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-026-13', 'p0019', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '五年，夏侯玄伐蜀，淮督諸軍為前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-14', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，儉與夏侯玄、李豊等厚善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-15', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '累遷御史中丞尚書，與夏侯玄、鄧颺等相善，收名朝廷，京都翕然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-16', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-033-17', 'p0019', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-039-18', 'p0019', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '夏侯玄、陳表並有騂角之美，而亦如泰者，魏書總名此卷云諸夏侯曹傳，故不復稍加品藻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-19', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '少流美譽，與夏侯玄、何晏齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-20', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-21', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '正元元年春正月，天子與中書令李豐、后父光祿大夫張緝、黃門監蘇鑠、永寧署令樂敦、冗從僕射劉寶賢等謀以太常夏侯玄代帝輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-22', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '大將軍曹爽之伐蜀也，以帝為征蜀將軍，副夏侯玄出駱谷，次于興勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-049-0', 'p0020', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '尚書令荀彧聞統名，竒之，舉為尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-067-1', 'p0020', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '甞稱「潁川荀彧，王佐之器」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-070-2', 'p0020', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '荀彧薦襲，太祖以為丞相軍謀祭酒，魏國建，為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-070-3', 'p0020', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '尚書令荀彧深建宜住之便，遠恢進討之略，恢，大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-074-4', 'p0020', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹乃使外甥陳留高幹及潁川荀諶等說馥曰：魏志云諶，荀彧之弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-099-5', 'p0020', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '後荀彧問仲長統以社所祭者何神也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-6', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-7', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧、程昱保鄄城，范、東阿二縣固守，太祖乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-8', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-9', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公與荀彧書曰：「賊來追吾，雖日行數里，吾策之，到安衆，破繡必矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-10', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧問公：「前以策賊必破，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-11', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公糧少，與荀彧書，議欲還許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-002-12', 'p0020', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '後軍南征次內蠡，尚書令荀彧奉使犒軍，見余談論之末，彧言：「聞君善左右射，此實難能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-004-13', 'p0020', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之以為故魏氏配饗不及荀彧，蓋以其末年異議，又位非魏臣故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-006-14', 'p0020', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '荊州平，太祖與荀彧書曰：「不喜得荊州，喜得蒯異度耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-15', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀彧字文若，潁川潁陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-16', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鍾繇以為顏子旣沒，能備九德，不貳其過，唯荀彧然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-17', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒旣奇太祖而知荀彧，袁紹慕之，與為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-18', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後荀彧為尚書令，遣人迎叔父司空爽喪，使并置顒尸，而葬之於爽冢傍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-19', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖素聞攸名，與語大恱，謂荀彧，鍾繇曰：「公達，非常人也，吾得與之計事，天下當何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-20', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '評曰：荀彧清秀通雅，有王佐之風，然機鑒先識，未能充其志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-011-21', 'p0020', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '尚書令荀彧、司隷校尉鍾繇亦以為可聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-011-22', 'p0020', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」　魏書載荀彧議，以為「君子之道，或出或處，期於為善而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-23', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-24', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖旣數聽荀彧之稱繇，又聞其說傕、汜，益虛心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-25', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '歆至，拜議郎，參司空軍事，入為尚書，轉侍中，代荀彧為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-26', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征徐州，使昱與荀彧留守鄄城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-27', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖與荀彧書曰：「自志才亡後，莫可與計事者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-28', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖與荀彧書，追傷嘉曰：「郭奉孝年不滿四十，相與周旋十一年，阻險艱難，皆共罹之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-29', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」獻帝春秋曰：昭與列侯諸將議，以丞相宜進爵國公，九錫備物，以彰殊勳；書與荀彧曰：「昔周旦、呂望，當姬氏之盛，因二聖之業，輔翼成王之幼，功勳若彼，猶受上爵，錫土開宇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-30', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '尚書令荀彧見資，歎曰：「北州承喪亂已乆，謂其賢智零落，今日乃復見孫計君乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-31', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '荀彧進之太祖，傅子曰：畿自荊州還，後至許，見侍中耿紀，語終夜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-32', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '尚書令荀彧與紀比屋，夜聞畿言，異之，旦遣人謂紀曰：「有國士而不進，何以居位？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-33', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖謂荀彧曰：「關西諸將，恃險與馬，征必為亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-34', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時四方大有還民，關中諸將多引為部曲，覬書與荀彧曰：「關中膏腴之地，頃遭荒亂，人民流入荊州者十萬餘家，聞本土安寧，皆企望思歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-35', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖使荀彧問覬，覬以為「西方諸將，皆豎夫屈起，無雄天下意，苟安樂目前而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-36', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」劭時在尚書令荀彧所，坐者數十人，或云當廢朝，或云宜却會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-37', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '漢帝在許，尚書令荀彧領典樞機，好士愛奇，聞統名，啟召以為尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-023-38', 'p0020', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '荀彧又薦襲，太祖以為丞相軍祭酒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-023-39', 'p0020', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」乃書與荀彧曰：「今陽安郡當送緜絹，道路艱阻，必致寇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-026-40', 'p0020', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-029-41', 'p0020', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '荀彧請曰：「佗術實工，人命所縣，宜含宥之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-037-42', 'p0020', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '儗之魏臣，統其荀彧之仲叔，正其程、郭之儔儷邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-038-43', 'p0020', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '陳國袁徽以寄寓交州，徽與尚書令荀彧書曰：「許文休英才偉士，智略足以計事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-049-44', 'p0020', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '陳國袁徽與尚書令荀彧書曰：「交阯士府君旣學問優博，又達於從政，處大亂之中，保全一郡，二十餘年疆埸無事，民不失業，羈旅之徒，皆蒙其慶，雖竇融保河西，曷以加之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a05-019-45', 'p0020', 'jinshu', 'a05-019', '《晉書·卷十九》', '朝士疑會否，共諮尚書令荀彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a05-019-46', 'p0020', 'jinshu', 'a05-019', '《晉書·卷十九》', '於時有謂邵為不得禮意，荀彧從之，是勝人之一失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-069-0', 'p0021', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '因復博徵智謀之士龐紀、何顒、荀攸等，與同腹心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-1', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '謂潁川人荀攸曰：「何公未易輔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-2', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '乃與何顒、荀攸共謀殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-3', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧又進操計謀之士從子攸，魏志，荀攸字公達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-4', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧使荀攸深自陳讓，至于十數，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-5', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公連戰，士卒罷，欲還，用荀攸、郭嘉計，遂決泗、沂水以灌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-6', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀攸說公曰：「今兵少不敵，分其勢乃可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-7', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀攸曰：「此所以餌敵，如何去之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-8', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-9', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '左右疑之，荀攸、賈詡勸公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-10', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-11', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-12', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-004-13', 'p0021', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月癸卯，詔祀故尚書令荀攸於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-004-14', 'p0021', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-15', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧言「荀攸、鍾繇」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-16', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」太祖欲表彧為三公，彧使荀攸深讓，至于十數，太祖乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-17', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-18', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸後為魏尚書令，亦推賢進士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-19', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸字公達，彧從子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-20', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '兾州平，太祖表封攸曰：「軍師荀攸，自初佐臣，無征不從，前後克敵，皆攸之謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-21', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸、賈詡，庶乎筭無遺策，經達權變，其良、平之亞與！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-013-22', 'p0021', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-013-23', 'p0021', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '靈帝崩，何進輔政，徵河南鄭泰、潁川荀攸及歆等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-014-24', 'p0021', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及薨，臨其喪，哀甚，謂荀攸等曰：「諸君年皆孤輩也，唯奉孝最少。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-014-25', 'p0021', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-016-26', 'p0021', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾兄泰，與荀攸等謀誅董卓，為揚州刺史，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-016-27', 'p0021', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '謂潁川人荀攸曰：「何公未易輔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-029-28', 'p0021', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '初，潁川荀攸、鍾繇相與親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a05-039-29', 'p0021', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '昔魏武帝使中軍司荀攸典刑獄，明帝時猶以付內常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-009-0', 'p0022', 'houhanshu', 'a03-009', '《後漢書·卷九》', '賈詡奏曰：『立司候不明，疑誤上下，請付理官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-010b-full-1', 'p0022', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」尚書賈詡知之，魏志曰：「詡字文和，武威姑臧人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-071-2', 'p0022', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」會李傕用太尉周忠、尚書賈詡策，徵儁入朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-3', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '武威人賈詡時在傕軍，說之曰：魏志曰：「卓之入洛陽，詡以太尉掾為平津尉，遷討虜校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-4', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以賈詡為左馮翊，欲侯之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-5', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '前涼州刺史种劭、中郎將杜稟合兵攻傕，獻帝紀曰：「稟與賈詡有隙，脅扶風吏人為騰守槐里，欲共攻傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-108-6', 'p0022', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '尚書賈詡奏曰：『立伺候不明，疑誤上下；太尉周忠，職所典掌，請皆治罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-7', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '左右疑之，荀攸、賈詡勸公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-8', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '超等數挑戰，又不許；固請割地，求送任子，公用賈詡計，偽許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-9', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-002-10', 'p0022', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-002-11', 'p0022', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-12', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '用賈詡策，遂將其衆而西，所在收兵，比至長安，衆十餘萬，九州春秋曰：傕等在陝，皆恐怖，急擁兵自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-13', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '賈詡曰「此上意，不可拒」，傕不從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-14', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」於是天子一乘，貴人伏氏一乘，賈詡、左靈一乘，其餘皆步從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-008-15', 'p0022', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：繡降，用賈詡計，乞徙軍就高道，道由太祖屯中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-008-16', 'p0022', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖拒袁紹於官渡，繡從賈詡計，復以衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-17', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '賈詡字文和，武威姑臧人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-18', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '當是時，元惡旣梟，天地始開，致使厲階重結，大梗殷流，邦國遘殄悴之哀，黎民嬰周餘之酷，豈不由賈詡片言乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-19', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔魏文帝用賈詡為三公，孫權笑之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-20', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸、賈詡，庶乎筭無遺策，經達權變，其良、平之亞與！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-014-21', 'p0022', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖謂賈詡曰：「程昱之膽，過於賁、育。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-036-22', 'p0022', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公用賈詡謀，離間超、遂，更相猜疑，軍以大敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a03-070-0', 'p0023', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」及鍾繇、郭嘉、魏志，嘉字奉孝，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-1', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公連戰，士卒罷，欲還，用荀攸、郭嘉計，遂決泗、沂水以灌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-2', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-3', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」郭嘉亦勸公，遂東擊備，破之，生禽其將夏侯博。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-4', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」惟郭嘉策表必不能任備，勸公行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-004-5', 'p0023', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-004-6', 'p0023', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲，詔祀故軍祭酒郭嘉於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-010-7', 'p0023', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '取士不以一揆，戲志才、郭嘉等有負俗之譏，杜畿簡傲少文，皆以智策舉之，終各顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-010-8', 'p0023', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與郭嘉說曰：「呂布勇而無謀，今三戰皆北，其銳氣衰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-9', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後又遣備至徐州要擊袁術，昱與郭嘉說太祖曰：「公前日不圖備，昱等誠不及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-10', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '郭嘉字奉孝，潁川陽翟人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-11', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」乃表曰：「軍祭酒郭嘉，自從征伐，十有一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-12', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '故軍祭酒郭嘉，忠良淵淑，體通性達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-13', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-025-14', 'p0023', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '他日置酒，毗望太祖色，知有變，以語郭嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-032-15', 'p0023', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏武帝遣先主統諸將要擊袁術，郭嘉等並諫，魏武不從，其事顯然，非因種菜遁逃而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a03-070-0', 'p0024', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧乃使程昱說范、東阿，魏志：「昱字仲德，東郡東阿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-1', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-2', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧、程昱保鄄城，范、東阿二縣固守，太祖乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-3', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱止太祖，太祖從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-4', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-5', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱說公曰：「觀劉備有雄才而甚得衆心，終不為人下，不如早圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-6', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-7', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-003-8', 'p0024', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏五月壬申，詔祀故大將軍夏侯惇、大司馬曹仁、車騎將軍程昱於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-004-9', 'p0024', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-010-10', 'p0024', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '又與程昱計，使說范、東阿，卒全三城，以待太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-11', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '程昱字仲德，東郡東阿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-12', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」岱議連日不決，別駕王彧白岱：「程昱有謀，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-13', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖謂賈詡曰：「程昱之膽，過於賁、育。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-14', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖使備要擊袁術，嘉與程昱俱駕而諫太祖曰：「放備，變作矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-15', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-018-16', 'p0024', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖擊譚、尚於黎陽，使典與程昱等以船運軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-036-17', 'p0024', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，飛雄壯威猛，亞於關羽，魏謀臣程昱等咸稱羽、飛萬人之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-031-0', 'p0025', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '其諸臧過者，望風解印綬去，唯癭陶長濟陰董昭、觀津長梁國黃就當官待琮，於是州界翕然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-1', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '十七年，董昭等昭字公仁，濟陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-2', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '至董昭建魏公議，彧意不同，欲言之於太祖，乃齎璽書犒軍，飲饗禮畢，彧請間，太祖知彧欲言，揖而遣之，遂不得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-3', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及阻董昭之議，以致非命，豈數也夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-001-4', 'p0025', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '洛陽殘破，董昭等勸太祖都許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-001-5', 'p0025', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-003-6', 'p0025', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '秋七月，以衞尉董昭為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-003-7', 'p0025', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '五月乙卯，司徒董昭薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-008-8', 'p0025', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載董昭表曰：「武皇帝承涼州從事及武都降人之辭，說張魯易攻，陽平城下南北山相遠，不可守也，信以為然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-010-9', 'p0025', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '十七年，董昭等謂太祖宜進爵國公，九錫備物，以彰殊勳，密以諮彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-010-10', 'p0025', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '至董昭建立魏公之議，彧意不同，欲言之於太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-012-11', 'p0025', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會內官欲以事託芝，不敢發言，因芝妻伯父董昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-014-12', 'p0025', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '董昭字公仁，濟陰定陶人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-014-13', 'p0025', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-016-14', 'p0025', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '徵拜侍中，與董昭同寮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-021-15', 'p0025', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '質自以不為本郡所饒，謂司徒董昭曰：「我欲溺鄉里耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a05-013-16', 'p0025', 'jinshu', 'a05-013', '《晉書·卷十三》', '四年五月，司徒董昭薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-002-0', 'p0026', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」　魏王侍中劉廙、辛毗、劉曄、尚書令桓階、尚書陳矯、陳羣、給事黃門侍郎王毖、董遇等言：「臣伏讀左中郎將李伏上事，考圖緯之言，以效神明之應，稽之古代，未有不然者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-002-1', 'p0026', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」於是侍中辛毗、劉曄、散騎常侍傅巽、衞臻、尚書令桓階、尚書陳矯、陳羣、給事中博士騎都尉蘇林、董巴等奏曰：「伏見太史丞許芝上魏國受命之符；令書懇切，允執謙讓，雖舜、禹、湯、文，義無以過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-003-2', 'p0026', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '居數日，獨見侍中劉曄，語盡日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-008-3', 'p0026', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '侍中辛毗、劉曄等在兵後，語惇、褚，言『官兵已據得賊要屯，賊已散走』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-010-4', 'p0026', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-012-5', 'p0026', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」侍中劉曄對曰：「獵勝於樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-012-6', 'p0026', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」因奏：「劉曄佞諛不忠，阿順陛下過戲之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-7', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉曄字子揚，淮南成悳人，悳音德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-8', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣言誠不足采，侍中劉曄先帝謀臣，常曰蜀不可伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-9', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-017-10', 'p0026', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '帝遣侍中劉曄將太醫視疾，虎賁問消息，道路相屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-022-11', 'p0026', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '世語曰：劉曄以先進見幸，因譖矯專權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-022-12', 'p0026', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」旣入，盡日，帝曰：「劉曄構君，朕有以迹君；朕心故已了。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-025-13', 'p0026', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '文帝問侍中劉曄等：「武都太守何如人也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-026-14', 'p0026', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '臣松之案：曁字休先，熒陽人，事見劉曄傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-037-15', 'p0026', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '劉曄曰：「子昭拔自賈豎，年至耳順，退能守靜，進能不苟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-047-16', 'p0026', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '珩還言曰：「臣密參侍中劉曄，數為賊設姦計，終不乆愨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-004-0', 'p0027', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙酉，以領軍將軍蔣濟為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-1', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '干寶晉書曰：桓範出赴爽，宣王謂蔣濟曰：「智囊往矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-2', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」　世語曰：宣王使許允、陳泰解語爽，蔣濟亦與書達宣王之旨，又使爽所信殿中校尉尹大目謂爽，唯免官而已，以洛水為誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-3', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '中護軍蔣濟表曰：「畢軌前失，旣往不咎，但恐是後難可以再。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-4', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '蔣濟為太尉，嘗與範會社下，羣卿列坐有數人，範懷其所撰，欲以示濟，謂濟當虛心觀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-5', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '干寶晉紀曰：蔣濟以曹真之勳力，不宜絕祀，故以熈為後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-6', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '故蔣濟為護軍時，有謠言「欲求牙門，當得千匹；百人督，五百匹」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-013-7', 'p0027', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '肅與太尉蔣濟、司農桓範論及時政，肅正色曰：「此輩即弘恭、石顯之屬，復稱說邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-8', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖徵曄及蔣濟、胡質等五人，皆揚州名士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-9', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '蔣濟字子通，楚國平阿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-10', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」民有誣告濟為謀叛主率者，太祖聞之，指前令與左將軍于禁、沛相封仁等曰：「蔣濟寧有此事！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-11', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '蔣濟諫曰：「凡非相吞之國，不侵叛之臣，不宜輕伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-12', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣松之案蔣濟立郊議稱曹騰碑文云「曹氏族出自邾」，魏書述曹氏胤緒亦如之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-13', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫盛曰：蔣濟之辭邑，可謂不負心矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-14', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '語曰「不為利回，不為義疚」，蔣濟其有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-15', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-015-16', 'p0027', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '』得無當得蔣濟為治中邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-021-17', 'p0027', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太尉蔣濟聞而辟之，後為尚書郎、曹爽參軍，以疾歸田里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-022-18', 'p0027', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '中護軍蔣濟遺臻書曰：「漢祖遇亡虜為上將，周武拔漁父為太師；布衣厮養，可登王公，何必守文，試而後用？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-19', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '揚州治在其縣，時蔣濟為治中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-20', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '苗恚恨還，刻木為人，署曰「酒徒蔣濟」，置之牆下，旦夕射之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-21', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '如所忿蔣濟者，仕進至太尉，濟不以苗前毀己為嫌，苗亦不以濟貴更屈意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-025-22', 'p0027', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '初，太和中，中護軍蔣濟上疏曰「宜遵古封禪」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-026-23', 'p0027', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」護軍將軍蔣濟議，以為：「旣示天下以弱，且望賊煙火而壞城，此為未攻而自拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-027-24', 'p0027', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '少與蔣濟、朱績俱知名於江、淮間，仕州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-027-25', 'p0027', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '蔣濟為別駕，使見太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-028-26', 'p0027', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '太傅嘗從容問蔣濟，濟曰：「淩文武俱贍，當今無雙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-028-27', 'p0027', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '中護軍蔣濟著論，謂「觀其眸子，足以知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-036-28', 'p0027', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-037-29', 'p0027', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '蔣濟萬機論云許子將襃貶不平，以拔樊子昭而抑許文休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-037-30', 'p0027', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '至於友于不穆，失由子將，尋蔣濟之論，知非文休之尤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-038-31', 'p0027', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '評曰：許靖夙有名譽，旣以篤厚為稱，又以人物為意，雖行事舉動，未悉允當，蔣濟以為「大較廊廟器」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-32', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '大司農桓範出赴爽，蔣濟言於帝曰：「智囊往矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-33', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '帝親帥太尉蔣濟等勒兵出迎天子，屯于洛水浮橋，上奏曰：「先帝詔陛下、秦王及臣升於御牀，握臣臂曰『深以後事為念』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-34', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '蔣濟曰：「曹真之勳，不可以不祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-012-35', 'p0027', 'jinshu', 'a05-012', '《晉書·卷十二》', '蔣濟上疏曰：「昔大舜佐治，戒在比周。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-042-36', 'p0027', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '楚王瑋將害汝南王亮等也，公孫宏說瑋曰：「昔宣帝廢曹爽，引太尉蔣濟參乘，以增威重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-054-0', 'p0028', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕脅帝歸其營，竒與黃門侍郎鍾繇誘傕部曲將宋曅、楊昂令反傕，傕由此孤弱，帝乃得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-066-1', 'p0028', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '鍾繇字元常，魏太祖時為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-070-2', 'p0028', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」及鍾繇、郭嘉、魏志，嘉字奉孝，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-072-3', 'p0028', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-4', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '按鍾繇傳云：「公與紹相持，繇為司隷，送馬二千餘匹以給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-5', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯據漢中，三月，遣鍾繇討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-6', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-7', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，以大理鍾繇為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-8', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '九月，相國鍾繇坐西曹掾魏諷反免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-9', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '世語曰：諷字子京，沛人，有惑衆才，傾動鄴都，鍾繇由是辟焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-002-10', 'p0028', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月丁卯，以廷尉鍾繇為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-003-11', 'p0028', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-004-12', 'p0028', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-004-13', 'p0028', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-14', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧言「荀攸、鍾繇」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-15', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '鍾繇以問彧，彧曰：「公之聦明，必不追咎往事，殆有他慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-16', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-17', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '時有甲乙疑論，閎與鍾繇、王朗、袁渙議各不同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-18', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-19', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鍾繇以為顏子旣沒，能備九德，不貳其過，唯荀彧然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-20', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖素聞攸名，與語大恱，謂荀彧，鍾繇曰：「公達，非常人也，吾得與之計事，天下當何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-21', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與鍾繇善，繇言：「我每有所行，反覆思惟，自謂無以易；以咨公達，輒復過人意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-22', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '臣松之案：攸亡後十六年，鍾繇乃卒，撰攸奇策，亦有何難？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-23', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '尚書令荀彧、司隷校尉鍾繇亦以為可聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-24', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '鍾繇以為「原思辭粟，仲尼不與，子路拒牛，謂之止善，雖可以激清勵濁，猶不足多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-25', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」相國鍾繇謂脩：「舊，京城有變，九卿各居其府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-26', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，昭善史書，與鍾繇、邯鄲淳、衞覬、韋誕並有名，尺牘之迹，動見模楷焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-012-27', 'p0028', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '大理鍾繇詰玠曰：「自古聖帝明王，罪及妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-012-28', 'p0028', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-29', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '鍾繇字元常，頴川長社人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-30', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-31', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '謹桉侍中守司隷校尉東武亭侯鍾繇，幸得蒙恩，以斗筲之才，仍見拔擢，顯從近密，銜命督使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-32', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '鍾繇明察當法，俱以治獄見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-33', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '至黃初初，朗又與太尉鍾繇連名表聞，兼稱登在職勤勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-34', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '司隷鍾繇在東，識其文，曰：「此賈洪作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-35', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-015-36', 'p0028', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '鍾繇、王粲著論云：「非聖人不能致太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-015-37', 'p0028', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司隷校尉鍾繇遣旣說將軍馬騰等，旣為言利害，騰等從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-018-38', 'p0028', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-021-39', 'p0028', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾繇、王朗等雖各為魏卿相，至於朝廷奏議，皆閣筆不能措手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-021-40', 'p0028', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾繇求以三千兵入關，外託討張魯，內以脅取質任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-022-41', 'p0028', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」時鍾繇與羣議同，王朗及議者多以為未可行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-42', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '是時科禁長吏擅去官，而黃聞司徒趙溫薨，自以為故吏，違科奔喪，為司隷鍾繇所收，遂伏法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-43', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '司隷鍾繇表拜議郎參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-44', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '司隷鍾繇不好公羊而好左氏，謂左氏為太官，而謂公羊為賣餅家，故數與幹共辯析長短。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-024-45', 'p0028', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-028-46', 'p0028', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '宣王為泰會，使尚書鍾繇調泰：「君釋褐登宰府，三十六日擁麾蓋，守兵馬郡；乞兒乘小車，一何駛乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-028-47', 'p0028', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　臣松之案：鍾繇于時老矣，而方納正室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-029-48', 'p0028', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '初，潁川荀攸、鍾繇相與親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-032-49', 'p0028', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-032-50', 'p0028', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後為五官將司馬，相國鍾繇長史，年六十餘卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-036-51', 'p0028', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '司隷校尉鍾繇鎮關中，移書遂、騰，為陳禍福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-036-52', 'p0028', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安之初，國家綱紀始弛，乃使司隷校尉鍾繇、涼州牧韋端和解之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a05-019-53', 'p0028', 'jinshu', 'a05-019', '《晉書·卷十九》', '及文帝崩，太尉鍾繇告謚南郊，皆是有事於郊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a05-039-54', 'p0028', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '從外祖魏太傅鍾繇曰：「此兒當及其曾祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-009-0', 'p0029', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二十二年夏六月，丞相軍師華歆為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-010b-full-1', 'p0029', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」又以尚書令華歆為郗慮副，魏志曰：「華歆字子魚，平原高唐人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-010b-2', 'p0029', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」又以尚書令華歆爲郗慮副，〈《魏志》曰：「華歆字子魚，平原高唐人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-053-3', 'p0029', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '太守華歆禮請相見，固病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-110-4', 'p0029', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '庚午，登壇，魏相國華歆跪受璽綬，以進於王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-001-5', 'p0029', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '曹瞞傳曰：公遣華歆勒兵入宮收后，后閉戶匿壁中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-001-6', 'p0029', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '六月，以軍師華歆為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-7', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '今使使持節御史大夫華歆奉策詔授丕丞相印綬、魏王璽紱，領兾州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-8', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-9', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-003-10', 'p0029', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-004-11', 'p0029', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-004-12', 'p0029', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　魏名臣奏載太尉華歆表曰：「臣聞勵俗宣化，莫先於表善，班祿敘爵，莫美於顯能，是以楚人思子文之治，復命其胤，漢室嘉江公之德，用顯其世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-010-13', 'p0029', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-14', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '與平原華歆、同縣邴原相友，俱游學於異國，並敬善陳仲弓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-15', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '黃初四年，詔公卿舉獨行君子，司徒華歆薦寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-16', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '明帝即位，太尉華歆遜位讓寧，傅子曰：司空陳羣又薦寧曰：「臣聞王者顯善以消惡，故湯舉伊尹，不仁者遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-17', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '黃初四年，高祖文皇帝疇咨羣公，思求儁乂，故司徒華歆舉寧應選，公車特徵，振翼遐裔，翻然來翔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-012-18', 'p0029', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-19', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時司徒華歆、司空王朗，並先世名臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-20', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時華歆亦以高年疾病，朝見皆使載輿車，虎賁舁上殿就坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-21', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '華歆字子魚，平原高唐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-22', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-016-23', 'p0029', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '時華歆為豫章太守，素與泰善，渾乃渡江投歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-035-24', 'p0029', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮集曰：是歲，魏司徒華歆、司空王朗、尚書令陳羣、太史令許芝、謁者僕射諸葛璋各有書與亮，陳天命人事，欲使舉國稱藩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-038-25', 'p0029', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '始靖兄事潁川陳紀，與陳郡袁渙、平原華歆、東海王朗等親善，歆、朗及紀并子羣，魏初為公輔大臣，咸與靖書，申陳舊好，情義欵至，文多故不載。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-046-26', 'p0029', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '勳糧食少，無以相振，乃遣從弟偕告糴於豫章太守華歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-047-27', 'p0029', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '年十一，華歆行風俗，見而異之，因呼曰：「沈郎，可登車語乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-057-28', 'p0029', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」翻別傳曰：朗使翻見豫章太守華歆，圖起義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-057-29', 'p0029', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '統母改適，為華歆小妻，統時八歲，遂與親客歸會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-037-0', 'p0030', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '後東適會稽，住止山陰縣故魯相鍾離意舍，太守王朗餉給糧食、布帛、牛羊，一無所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-045-1', 'p0030', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '一見太守王朗徒從整飾，心嫌之，遂稱病自絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-045-2', 'p0030', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '王朗字景興，肅之父也，魏志有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-049-3', 'p0030', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '其後王朗為會稽太守，又得其書，及還許下，時人稱其才進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-080b-4', 'p0030', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '府掾孔融、王朗並修刺候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-001-5', 'p0030', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-6', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-7', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-8', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏氏春秋曰：明帝將送葬，曹真、陳羣、王朗等以暑熱固諫，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-9', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書曰：帝初在東宮，疫癘大起，時人彫傷，帝深感歎，與素所敬者大理王朗書曰：「生有七尺之形，死為一棺之土，唯立德揚名，可以不朽，其次莫如著篇籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-003-10', 'p0030', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-004-11', 'p0030', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-004-12', 'p0030', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月辛亥，詔故司徒王朗所作易傳，令學者得以課試。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-005-13', 'p0030', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明帝即位，有司奏請追謚，使司空王朗持節奉策以太牢告祠于陵，又別立寢廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-007-14', 'p0030', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-010-15', 'p0030', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '時有甲乙疑論，閎與鍾繇、王朗、袁渙議各不同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-010-16', 'p0030', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-17', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時司徒華歆、司空王朗，並先世名臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-18', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」司徒王朗議，以為「繇欲輕減大辟之條，以增益刖刑之數，此即起偃為豎，化屍為人矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-19', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '王朗字景興，東海郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-20', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '策令使者詰朗曰：「問逆賊故會稽太守王朗：朗受國恩當官，云何不惟報德，而阻兵安忍？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-21', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」王朗集載朗為大理時上主簿趙郡張登：「昔為本縣主簿，值黑山賊圍郡，登與縣長王儁帥吏兵七十二人直往赴救，與賊交戰，吏兵散走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-22', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-017-23', 'p0030', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及太祖領兖州，禁與其黨俱詣為都伯，屬將軍王朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-021-24', 'p0030', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾繇、王朗等雖各為魏卿相，至於朝廷奏議，皆閣筆不能措手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-022-25', 'p0030', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」時鍾繇與羣議同，王朗及議者多以為未可行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-027-26', 'p0030', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '頃之，司徒王朗辟基，淩不遣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-035-27', 'p0030', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮集曰：是歲，魏司徒華歆、司空王朗、尚書令陳羣、太史令許芝、謁者僕射諸葛璋各有書與亮，陳天命人事，欲使舉國稱藩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-035-28', 'p0030', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-29', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '禕死，吳郡都尉許貢、會稽太守王朗素與靖有舊，故往保焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-30', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '始靖兄事潁川陳紀，與陳郡袁渙、平原華歆、東海王朗等親善，歆、朗及紀并子羣，魏初為公輔大臣，咸與靖書，申陳舊好，情義欵至，文多故不載。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-31', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '魏略：王朗與文休書曰：「文休足下：消息平安，甚善甚善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-042-32', 'p0030', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '魏太子荅王朗書曰：「昔石厚與州吁游，父碏知其與亂；韓子昵田蘇，穆子知其好仁：故君子游必有方，居必就士，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-046-33', 'p0030', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」術知其恨，而以劉繇據曲阿，王朗在會稽，謂策未必能定，故許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-049-34', 'p0030', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '王朗遺策書曰：「劉正禮昔初臨州，未能自達，實賴尊門為之先後，用能濟江成治，有所處定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-051-35', 'p0030', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '是時太守王朗拒策於固陵，策數渡水戰，不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-052-36', 'p0030', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少好學，善隷書，從白侯子安受左氏春秋，博覽衆書，與琅邪趙昱、東海王朗俱發名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-060-37', 'p0030', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '時王朗奔東冶，候官長商升為朗起兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a05-019-38', 'p0030', 'jinshu', 'a05-019', '《晉書·卷十九》', '明帝即位，有司奏請追謚曰文昭皇后，使司空王朗持節奉策告祠于陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a03-072-0', 'p0032', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '萌字文始，有才學，與王粲善，粲作詩贈萌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-1', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-2', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-3', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是行也，侍中王粲作五言詩以美其事，曰：「從軍有苦樂，但問所從誰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-006-4', 'p0032', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '萌字文始，亦有才學，與王粲善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-013-5', 'p0032', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其邯鄲淳事在王粲傳，蘇林事在劉邵、高堂隆傳，樂詳事在杜畿傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-015-6', 'p0032', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '鍾繇、王粲著論云：「非聖人不能致太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-7', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '王粲字仲宣，山陽高平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-8', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏侍中王粲識舊珮，始復作之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-9', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-10', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏國旣建，拜侍中，與王粲並典制度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-11', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-12', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏國旣建，為侍中，與王粲、和洽並用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-13', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '潛私謂所親王粲、司馬芝曰：「劉牧非霸王之才，乃欲西伯自處，其敗無日矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-028-14', 'p0032', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '博物記曰：初，王粲與族兄凱俱避地荊州，劉表欲以女妻粲，而嫌其形陋而用率，以凱有風貌，乃以妻凱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-061-15', 'p0032', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '吳書曰：濬為人聦察，對問有機理，山陽王粲見而貴異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a05-019-16', 'p0032', 'jinshu', 'a05-019', '《晉書·卷十九》', '魏氏承漢末大亂，舊章殄滅，命侍中王粲、尚書衞覬草創朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-058-0', 'p0033', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '紹興兵圍之，歷年不下，使洪邑人陳琳以書譬洪，示其禍福，責以恩義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-069-1', 'p0033', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '主簿陳琳入諫曰：「易稱『即鹿無虞』，易屯卦六三爻辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-070-2', 'p0033', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安初，以高第擢拜尚書郎，後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-070-3', 'p0033', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '陳琳為紹作檄書曰：「操祖父騰饕餮放橫，父嵩乞匄攜養，操贅閹遺醜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-073-4', 'p0033', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」紹候得其書，獻帝春秋「候者得書，紹使陳琳易其詞」，即此書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-074-5', 'p0033', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '據陳琳集，此檄陳琳之詞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-074-6', 'p0033', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」流俗本此下有「陳琳之辭」者，非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-080b-7', 'p0033', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-001-8', 'p0033', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '故豫州刺史陰夔及陳琳乞降，公不許，為圍益急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-006-9', 'p0033', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '未合，尚懼，遣陰夔、陳琳乞降，不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-007-10', 'p0033', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '紹令洪邑人陳琳書與洪，喻以禍福，責以恩義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-008-11', 'p0033', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹候者得之，使陳琳更其書曰：「蓋聞在昔衰周之世，僵戶流血，以為不然，豈意今日身當其衝！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-012-12', 'p0033', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '琰稱疾固辭，由是獲罪，幽於囹圄，賴陰夔、陳琳營救得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-13', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-14', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-15', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粹後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-023-16', 'p0033', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-052-17', 'p0033', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '弱冠察孝廉，不就，與朗共論舊君諱事，州里才士陳琳等皆稱善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-053-18', 'p0033', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '陳琳在北見之，以示人曰：「此吾鄉里張子綱所作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-053-19', 'p0033', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」後紘見陳琳作武庫賦、應機論，與琳書深歎美之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-012-0', 'p0034', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '庶子劉楨書諫植曰：「家丞邢顒，北土之彥，少秉高節，玄靜澹泊，言少理多，真雅士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-1', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '東平劉楨字公幹並見友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-2', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-3', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '應瑒和而不壯；劉楨壯而不密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-4', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '及河北平定，五官將為世子，質與劉楨等並在坐席。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-029-5', 'p0034', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '後東平劉楨夢蛇生四足，穴居門中，使宣占之，宣曰：「此為國夢，非君家之事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-0', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '平陵人徐幹素與超同志，上疏願奮身佐超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-1', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '會徐幹適至，超遂與幹擊番辰，大破之，斬首千餘級，多獲生口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-2', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '以徐幹為軍司馬，別遣衞候李邑護送烏孫使者，賜大小昆彌以下錦帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-3', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '徐幹謂超曰：「邑前親毀君，欲敗西域，今何不緣詔書留之，更遣它吏送侍子乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-4', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '明年，龜茲、姑墨、溫宿皆降，乃以超為都護，徐幹為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-5', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '超居龜茲它乾城，徐幹屯疏勒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-080b-6', 'p0035', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-7', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-8', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-9', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '而粲特處常伯之官，興一代之制，然其沖虛德宇，未若徐幹之粹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a03-080b-0', 'p0036', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-1', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-2', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-3', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '應瑒和而不壯；劉楨壯而不密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a03-070-0', 'p0037', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安初，以高第擢拜尚書郎，後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a03-080b-1', 'p0037', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-2', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-3', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-4', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粹後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-023-5', 'p0037', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-0', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '丁儀等見寵於時，並害之，而弈終不為動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-1', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '丁儀方貴重，宜思所以下之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-2', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰、徐弈，一時清賢，皆以忠信顯於魏朝；丁儀間之，徐弈失位而崔琰被誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-3', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏書曰：時丁儀兄弟方進寵，儀與夔不合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-4', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '初，太子未定，而臨菑侯植有寵，丁儀等並贊翼其美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-5', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」植旣以才見異，而丁儀、丁廙、楊脩等為之羽翼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-6', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '世語曰：脩年二十五，以名公子有才能，為太祖所器，與丁儀兄弟，皆欲以植為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-7', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '文帝即王位，誅丁儀、丁廙并其男口。');
